define actor Foo as
    state { let int count: 0; }
    state machine as
        initial state Idle;
        state Idle as
            on Start() -> Running;
        end
        state Running as
            on Stop() -> Idle;
        end
    end
end

define actor Foo as
    state {}
    state machine as
        initial state Zed;
        final state Alpha;
        state Zed as
            on Zulu() -> Zed;
            on AlphaEvent() -> Alpha;
        end
    end
end
